import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;

/** A discount percentage typed by a person, as whole basis points (12.5 is 1250). */
final class DiscountPercent {

    private static final long BASIS_POINTS_IN_WHOLE = 10_000;

    private DiscountPercent() {
    }

    /**
     * Parses text such as "12", "12.5" or "12.50" into basis points, 0 to 10000 inclusive.
     * At most two decimal places are accepted: a finer rate cannot be represented.
     */
    static long parseBasisPoints(String text) {
        String s = null == text ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);

        if (whole.isEmpty() || whole.length() > 3 || !allDigits(whole)) {
            throw invalid(text);
        }
        if (dot >= 0 && (fraction.isEmpty() || fraction.length() > 2 || !allDigits(fraction))) {
            throw invalid(text);
        }

        long basisPoints = Long.parseLong(whole) * 100;
        if (!fraction.isEmpty()) {
            long hundredths = Long.parseLong(fraction);
            basisPoints += fraction.length() == 1 ? hundredths * 10 : hundredths;
        }
        if (basisPoints > BASIS_POINTS_IN_WHOLE) {
            throw invalid(text);
        }
        return basisPoints;
    }

    /** The part of the total that a rate takes, rounded half up to a whole minor unit. */
    static Money of(Money total, long basisPoints) {
        long product = Math.multiplyExact(total.minorUnits(), basisPoints);
        long discount = Math.floorDiv(product + BASIS_POINTS_IN_WHOLE / 2, BASIS_POINTS_IN_WHOLE);
        return new Money(discount, total.currency());
    }

    private static boolean allDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem invalid(String text) {
        return new ShopProblem("invalid-discount", "Not a discount percentage from 0 to 100: " + text);
    }
}
}

